pub use backend::{Backend, Sandbox};
pub use config::{FilesystemRule, NetworkPolicy, SandboxConfig, SandboxConfigBuilder};

/// Output from a sandboxed process execution.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SandboxOutput {
    /// Captured stdout (UTF-8 lossy)
    pub stdout: String,
    /// Captured stderr (UTF-8 lossy)
    pub stderr: String,
    /// Exit status code
    pub exit_code: i32,
    /// Whether the sandbox was actually enforced (false on `Disabled` backend)
    pub sandboxed: bool,
}

/// Errors that can occur when running a sandboxed command.
#[derive(Debug, thiserror::Error)]
pub enum SandboxError {
    #[error("command not found: {0}")]
    CommandNotFound(String),

    #[error("backend '{0}' is not available on this platform")]
    BackendUnavailable(&'static str),

    #[error("config validation failed: {0}")]
    InvalidConfig(String),

    #[error("sandbox setup failed: {0}")]
    SetupFailed(String),

    #[error("process spawn failed: {0}")]
    SpawnFailed(#[from] std::io::Error),

    #[error("execution timed out after {0:?}")]
    Timeout(std::time::Duration),
}

impl SandboxOutput {
    /// Returns true if the process exited with a non-zero status.
    pub fn failed(&self) -> bool {
        self.exit_code != 0
    }

    /// Returns the combined stdout + stderr output.
    pub fn combined_output(&self) -> String {
        if self.stderr.is_empty() {
            self.stdout.clone()
        } else if self.stdout.is_empty() {
            self.stderr.clone()
        } else {
            format!("{}\n{}", self.stdout, self.stderr)
        }
    }
}
